void point2ScreenQuad( geometryInS inputs[1], float2 pointSz, float2 screenSize, float4 quadPositionUV[4], 
     float4 chartQuad, float2 placement, inout TriangleStream<geometryInS> outStream  ) 
{ 
    float zIn = inputs[0].Pc.z / inputs[0].Pc.w; 
    if (zIn < 0 || zIn > 1) return; 
    geometryInS outS  = inputs[0]; 
    float2 sizeIn = pointSz / screenSize;  
    [unroll] for( int i = 0; i < 4; ++i ) { 
        float2 chartPlacement = quadPositionUV[i].xy + placement; 
        outS.Pc.xy = inputs[0].Pc.xy / inputs[0].Pc.w 
           + sizeIn * chartQuad.zw * chartPlacement; 
        outS.Pc.zw = float2(max(zIn, 0.001), 1.0); 
		 float2 uv = chartQuad.xy  
           + chartQuad.zw * quadPositionUV[i].zw; 
		 outS.UVFromGS = float3( uv, 0.0f); 
        outStream.Append( outS ); 
    } 
    outStream.RestartStrip(); 
}


void point2ScreenQuad( AttribArray<geometryInS>inputs, float2 pointSz, float2 screenSize, float4 quadPositionUV[4], 
    float4 chartQuad, float2 placement ) 
{ 
    float zIn = inputs[0].Pc.z / inputs[0].Pc.w; 
    if (zIn < -1 || zIn > 1) return; 
    geometryInS outS  = inputs[0]; 
    float2 sizeIn = pointSz  / screenSize;  
    for( int i = 0; i < 4; ++i ) { 
        float2 chartPlacement = quadPositionUV[i].xy + placement; 
        outS.Pc.xy = inputs[0].Pc.xy / inputs[0].Pc.w 
           + sizeIn * chartQuad.zw * chartPlacement; 
        outS.Pc.zw = float2(min(zIn, -0.999), 1.0); 
		 float2 uv = chartQuad.xy + chartQuad.zw * quadPositionUV[i].zw; 
		 outS.UVFromGS = float3( uv, 0.0f); 
        emitVertex( outS ); 
    } 
    restartStrip(); 
}


void point2ScreenQuad(  vec2 pointSz, vec2 screenSize, vec4 quadPositionUV[4], 
    vec4 chartQuad, vec2 placement ) 
{ 
    float zIn = gl_in[0].gl_Position.z / gl_in[0].gl_Position.w; 
    if (zIn < -1 || zIn > 1) return; 
    GEO_OUT_struct outS  = copyFromGEO_IN(0); 
    vec2 sizeIn = pointSz  / screenSize;  
    for( int i = 0; i < 4; ++i ) { 
        vec2 chartPlacement = quadPositionUV[i].xy + placement; 
        outS.Pc.xy = gl_in[0].gl_Position.xy / gl_in[0].gl_Position.w 
           + sizeIn * chartQuad.zw * chartPlacement; 
        outS.Pc.zw = vec2(min(zIn, -0.999), 1.0); 
		 vec2 uv = chartQuad.xy + chartQuad.zw * quadPositionUV[i].zw; 
		 outS.UVFromGS = vec3( uv, 0.0f); 
        EmitGeoStruct( outS ); 
    } 
    EndPrimitive(); 
}


void point2ScreenQuad( geometryInS inputs[1], float2 pointSz, float2 screenSize, float4 quadPositionUV[4], 
     float4 chartQuad, float2 placement, inout TriangleStream<geometryInS> outStream  ) 
{ 
    float zIn = inputs[0].Pc.z / inputs[0].Pc.w; 
    if (zIn < 0 || zIn > 1) return; 
    geometryInS outS  = inputs[0]; 
    float2 sizeIn = pointSz / screenSize;  
    [unroll] for( int i = 0; i < 4; ++i ) { 
        float2 chartPlacement = quadPositionUV[i].xy + placement; 
        outS.Pc.xy = inputs[0].Pc.xy / inputs[0].Pc.w 
           + sizeIn * chartQuad.zw * chartPlacement; 
        outS.Pc.zw = float2(max(zIn, 0.001), 1.0); 
		 float2 uv = chartQuad.xy  
           + chartQuad.zw * quadPositionUV[i].zw; 
		 outS.UVFromGS = float3( uv, 0.0f); 
        outStream.Append( outS ); 
    } 
    outStream.RestartStrip(); 
}
